window.customCards=window.customCards||[];window.customCards.push({type:'dashboard-robot',name:'Pakkerobot',description:'Animeret hjemmehjælper med spørgsmål og danske svar om hjemmet.'});

// Dashboard-scoped singleton. Configured dashboards use this robot; legacy robots resume elsewhere.
(() => {
  let config=null, profiles=[], robot=null, pending=false, lastFetch=0;
  const getHass=()=>document.querySelector('home-assistant')?.hass;
  const suppressed=new Map();
  function legacyRobots() {
    const queue=[document.querySelector('home-assistant'),...document.body.children].filter(Boolean),found=new Set(),seen=new Set();let count=0;
    while(queue.length&&count++<15000){
      const node=queue.pop();if(seen.has(node))continue;seen.add(node);
      if(node.localName==='home-parcel-robot'||node.localName?.endsWith('-wall-display-robot'))found.add(node);
      if(node.shadowRoot)queue.push(node.shadowRoot);
      for(const child of node.children||[])queue.push(child);
    }
    return found;
  }
  function setLegacySuppression(active) {
    if(!active){
      for(const [node,previous] of suppressed){
        if(previous.value)node.style.setProperty('display',previous.value,previous.priority);
        else node.style.removeProperty('display');
      }
      suppressed.clear();return;
    }
    for(const node of legacyRobots()){
      if(!node.style)continue;
      if(!suppressed.has(node)){
        suppressed.set(node,{value:node.style.getPropertyValue('display'),priority:node.style.getPropertyPriority('display')});
        node._closeRobotChat?.();
        if(node._recognition)node._stopListening?.();
        if(node._utterance){window.speechSynthesis?.cancel();node._finishSpeech?.();}
      }
      node.style.setProperty('display','none','important');
    }
  }
  function sync() {
    const hass=getHass();if(!hass)return;
    const [,segment,view='']=location.pathname.split('/');
    const candidates=profiles.filter(p=>{const paths=Array.isArray(p.dashboard_paths)?p.dashboard_paths:(p.dashboard_paths||'').split(',');return paths.map(x=>x.trim().replace(/^\/+|\/+$/g,'')).includes(segment);});
    const nextConfig=candidates.find(p=>(p.view_paths||'').split(',').map(x=>x.trim()).filter(Boolean).includes(view))||candidates.find(p=>!(p.view_paths||'').trim())||null;
    if(JSON.stringify(nextConfig)!==JSON.stringify(config)){if(robot){robot.remove();robot=null;}config=nextConfig;}
    const selected=(Array.isArray(config?.dashboard_paths)?config.dashboard_paths:(config?.dashboard_paths||'').split(',')).map(p=>p.trim().replace(/^\/+|\/+$/g,''));
    const active=!!config&&selected.includes(segment);
    setLegacySuppression(active);
    if(!active){
      if(robot){robot.remove();robot=null;}return;
    }
    if(!robot){
      robot=document.createElement('dashboard-robot');robot.hass=hass;
      const sources=config.parcel_sources?[...config.parcel_sources]:[];
      for(const [entity,state] of Object.entries(hass.states)){
        if(config.parcel_sources||!(config.package_entities||[]).includes(entity))continue;
        const carrier=/postnord/i.test(entity)?'PostNord':/gls/i.test(entity)?'GLS':/dhl/i.test(entity)?'DHL':/posten_bring/i.test(entity)?'Bring':/\bdao[_ .]/i.test(entity)?'DAO':null;
        const kind=/klar_til_afhentning|awaiting_pickup/.test(entity)?'pickup':/indkommende_pakker|incoming_parcels/.test(entity)?'incoming':/leverede_pakker|delivered_parcels/.test(entity)?'delivered':null;
        if(carrier&&kind&&!/outgoing|udgaende/.test(entity))sources.push({entity,carrier,kind});
      }
      sources.sort((a,b)=>({pickup:0,incoming:1,delivered:2}[a.kind]-{pickup:0,incoming:1,delivered:2}[b.kind]));
      robot.setConfig({...config,sources});document.body.append(robot);
    }
    robot.hass=hass;
  }
  async function refresh(force=false){
    const hass=getHass();if(!hass?.connection||pending)return;
    if(!force&&Date.now()-lastFetch<30000){sync();return;}
    pending=true;lastFetch=Date.now();
    try{const next=await hass.callWS({type:'dashboard_robot/config'});profiles=Array.isArray(next)?next:next?[next]:[];}
    catch{profiles=[];config=null;}
    finally{pending=false;sync();}
  }
  setInterval(()=>{if(!document.hidden)refresh();},2000);
  window.addEventListener('location-changed',()=>refresh(true));
  window.addEventListener('popstate',()=>refresh(true));
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh(true);});
  refresh(true);
})();
